SELECT uc.target_type AS targetType, uc.target_id AS targetId, COUNT(*) AS collectCount, MAX(COALESCE( tr.name, -- 旅游线路 ess.name, -- 养老驿站 stp.plan_name, -- 研学方案 sta.activity_name, -- 研学活动 vh.homestay_name, -- 民宿 spu.title, -- 农产品 r.name -- 餐饮 )) AS targetName FROM user_collect uc LEFT JOIN tour_route tr ON uc.target_type = 'tour_route' AND CAST(uc.target_id AS UNSIGNED) = tr.id LEFT JOIN elderly_service_subject ess ON uc.target_type = 'elderly_station' AND CAST(uc.target_id AS UNSIGNED) = ess.id LEFT JOIN study_tour_plan stp ON uc.target_type = 'study_plan' AND CAST(uc.target_id AS UNSIGNED) = stp.id LEFT JOIN study_tour_activity sta ON uc.target_type = 'study_activity' AND CAST(uc.target_id AS UNSIGNED) = sta.id LEFT JOIN village_homestay vh ON uc.target_type = 'homestay' AND CAST(uc.target_id AS UNSIGNED) = vh.id LEFT JOIN spu ON uc.target_type = 'product' AND CAST(uc.target_id AS UNSIGNED) = spu.id LEFT JOIN restaurant r ON uc.target_type = 'restaurant' AND CAST(uc.target_id AS UNSIGNED) = r.id
AND uc.target_type = #{targetType}
AND uc.create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
GROUP BY uc.target_type, uc.target_id ORDER BY collectCount DESC, MAX(uc.create_time) DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT CONCAT(target_type, '_', target_id)) FROM user_collect
AND target_type = #{targetType}
AND create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
